import React from 'react';

const About = () => {
  return (
    <div className="pg" id="page-about">
      <div className="sec">
        <div className="agrid">
          <div className="aphwrap reveal">
            <p className="bexc">From customer support automation to content creation — the exact tools Clarix recommends to every client in their first AI audit.</p>
          </div>
          <div className="aphoto">
            {/* Placeholder for photo */}
            <div style={{ width: '100%', height: '100%', background: 'var(--bg)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '3rem' }}>📸</div>
          </div>
        </div>
        <div style={{ marginTop: '4rem', textAlign: 'center' }}>
          <h2 className="dp2" style={{ marginBottom: '1rem' }}>About Clarix</h2>
          <p className="blg" style={{ maxWidth: '600px', margin: '0 auto' }}>
            Clarix is India's premier AI Generalist agency, founded by Deepak Varma.
            We bridge the gap between powerful AI technology and real business results.
          </p>
        </div>
      </div>
    </div>
  );
};

export default About;
